.darma-loader-tw-video-buffer { position: relative; display: inline-flex; align-items: center; justify-content: center; width: var(--loader-size, 64px); height: var(--loader-size, 64px); }
.darma-loader-tw-video-buffer .darma-loader-tw-video-buffer__ring { position: absolute; top: 0; bottom: 0; left: 0; right: 0; border-radius: 9999px; border: calc(var(--loader-size, 64px) * .07) solid color-mix(in srgb, var(--loader-color, #ef4444) 20%, transparent); border-top-color: var(--loader-color, #ef4444); border-right-color: var(--loader-color, #ef4444); animation: darma-loader-tw-video-buffer-twSpin calc(var(--loader-speed, 1s) * 1.1) linear infinite; }
.darma-loader-tw-video-buffer .darma-loader-tw-video-buffer__play { position: relative; width: 0; height: 0; margin-left: 8%; border-top: calc(var(--loader-size, 64px) * .15) solid transparent; border-bottom: calc(var(--loader-size, 64px) * .15) solid transparent; border-left: calc(var(--loader-size, 64px) * .25) solid var(--loader-color, #ef4444); animation: darma-loader-tw-video-buffer-twBeat calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
@keyframes darma-loader-tw-video-buffer-twSpin { to { transform: rotate(360deg); } }
@keyframes darma-loader-tw-video-buffer-twBeat { 0%, 100% { opacity: .5; transform: scale(.88); } 50% { opacity: 1; transform: scale(1); } }

